# Price (in cents) of a group of `size` distinct books, with the discount
# applied: 1 -> $8.00, 2 -> $7.60 each, 3 -> $7.20 each, 4 -> $6.40 each,
# 5 -> $6.00 each.
PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    counts = Counter(basket)

    # Greedily form the largest possible group each round, always taking the
    # titles with the most remaining copies so no title is left behind.
    groups = []
    while counts:
        size = min(5, len(counts))
        for title, _ in counts.most_common(size):
            counts[title] -= 1
            if counts[title] == 0:
                del counts[title]
        groups.append(size)

    # A group of five plus a group of three costs $51.60, while two groups of
    # four cost $51.20 for the same eight books, so always make that trade.
    while 5 in groups and 3 in groups:
        groups.remove(5)
        groups.remove(3)
        groups.extend([4, 4])

    return sum(PRICES[size] for size in groups)
"}
